// as a sequence of XML elements, each representing a property
// of [aastypes.ISomething].
//
// The reading stops as soon as we encounter a non-start element, and we return
// that token as the `next` token.
func readSomethingAsSequence(
	decoder *xml.Decoder,
	current xml.Token,
) (instance aastypes.ISomething,
	next xml.Token,
	err error,
) {
	var theValues []aastypes.JsonValue
	var theTupleWithJson aascommon.Tuple4[string, aastypes.JsonValue, aastypes.JsonArray, aastypes.JsonObject]

	foundValues := false
	foundTupleWithJson := false

	for {
		var local string
		var ok bool
		local, current, ok, err = nextProperty(decoder, current, "ISomething")
		if err != nil {
			return
		}
		if !ok {
			break
		}

		var valueErr error
		switch local {
		case "values":
			if foundValues {
				valueErr = duplicatePropertyError(local)
				break
			}
			theValues, current, valueErr = readListOf(
				decoder, current, readAtV_jsonValue,
			)
			foundValues = true
		case "tupleWithJson":
			if foundTupleWithJson {
				valueErr = duplicatePropertyError(local)
				break
			}
			theTupleWithJson, current, valueErr = readTuple4(
				decoder, current,
				readAtV1_string,
				readAtV2_jsonValue,
				readAtV3_jsonArray,
				readAtV4_jsonObject,
			)
			foundTupleWithJson = true
		default:
			valueErr = xmlcommon.NewDeserializationError(
				"Unexpected property",
			)
		}

		current, err = concludeProperty(decoder, current, local, valueErr)
		if err != nil {
			return
		}
	}

	next = current

	if !foundValues {
		err = missingProperty("values")
		return
	}

	if !foundTupleWithJson {
		err = missingProperty("tupleWithJson")
		return
	}

	instance = aastypes.NewSomething(
		theValues,
		theTupleWithJson,
	)
	return
}

// De-serialize an instance of [aastypes.IClass] based on the `local` name
// of its start element.
//
// The `current` token is expected to point to the content of that start element, and
// the resulting `next` token points to its end element.
